// Temporary synthetic-only adapter experiment. Never expose a stock-library proxy.
package main

import (
	"bufio"
	"bytes"
	"crypto/sha256"
	"crypto/subtle"
	"crypto/tls"
	"crypto/x509"
	"encoding/hex"
	"encoding/json"
	"errors"
	"fmt"
	"io"
	"log"
	"mime/multipart"
	"net"
	"net/http"
	"net/url"
	"os"
	"path/filepath"
	"strings"
	"sync"
	"time"

	"github.com/gorilla/websocket"
)

const documentUUID = "fc2a3c9b-feea-40d1-9ac1-a8327f10edba"
const sourceHash = "ba5b3f78a6bc4900cae7f8e009d68f9628a3d25a0e234808bc8dfe71d9e7d1f5"
const localURL = "http://127.0.0.1:81"
const limit = 50 << 20

type config struct {
	Mode, Address, Certificate, Key, CA, Token, ServerID, JobID, Source, Output string
}
type command struct{ Operation, ServerID, JobID, UUID string }
type observation struct {
	Time                string            `json:"time"`
	Operation           string            `json:"operation"`
	Status              string            `json:"status"`
	USB                 map[string]string `json:"usb"`
	Addresses           []string          `json:"addresses"`
	Listeners           []string          `json:"listeners"`
	Disconnected        bool              `json:"disconnected"`
	PrivateEndpointOnly bool              `json:"private_endpoint_only"`
}

func main() {
	if len(os.Args) != 2 {
		log.Fatal("Usage: transport configuration.json")
	}
	data, err := os.ReadFile(os.Args[1])
	must(err)
	var c config
	must(json.Unmarshal(data, &c))
	if len(c.Token) < 32 || c.ServerID == "" || c.JobID == "" {
		log.Fatal("Experiment token and fixed server/job identity required")
	}
	switch c.Mode {
	case "desktop":
		must(desktop(c))
	case "tablet":
		must(tablet(c))
	default:
		log.Fatal("Mode must be desktop or tablet")
	}
}

func desktop(c config) error {
	must(os.Mkdir(c.Output, 0700))
	source, err := os.ReadFile(c.Source)
	if err != nil {
		return err
	}
	sum := sha256.Sum256(source)
	if hex.EncodeToString(sum[:]) != sourceHash {
		return errors.New("Synthetic source hash mismatch")
	}
	reports, err := os.OpenFile(filepath.Join(c.Output, "reports.jsonl"), os.O_CREATE|os.O_EXCL|os.O_WRONLY, 0600)
	if err != nil {
		return err
	}
	defer reports.Close()
	var mu sync.Mutex
	state := "pending"
	controls := make(chan string)
	mux := http.NewServeMux()
	authorized := func(w http.ResponseWriter, r *http.Request) bool {
		if subtle.ConstantTimeCompare([]byte(r.Header.Get("Authorization")), []byte("Bearer "+c.Token)) != 1 {
			http.Error(w, "Unauthorized", 401)
			return false
		}
		return true
	}
	mux.HandleFunc("/source", func(w http.ResponseWriter, r *http.Request) {
		if !authorized(w, r) {
			return
		}
		if r.Method != "GET" {
			http.Error(w, "Method", 405)
			return
		}
		w.Header().Set("Content-Type", "application/pdf")
		w.Write(source)
	})
	mux.HandleFunc("/result", func(w http.ResponseWriter, r *http.Request) {
		if !authorized(w, r) {
			return
		}
		if r.Method != "POST" || r.Header.Get("X-Server-ID") != c.ServerID || r.Header.Get("X-Job-ID") != c.JobID || r.Header.Get("X-Document-UUID") != documentUUID {
			http.Error(w, "Wrong origin", 409)
			return
		}
		mu.Lock()
		pending := state == "pending"
		mu.Unlock()
		if !pending {
			http.Error(w, "Request terminal", 409)
			return
		}
		data, err := io.ReadAll(http.MaxBytesReader(w, r.Body, limit))
		if err != nil || !bytes.HasPrefix(data, []byte("%PDF-")) {
			http.Error(w, "Invalid PDF", 400)
			return
		}
		mu.Lock()
		defer mu.Unlock()
		if state != "pending" {
			http.Error(w, "Request terminal", 409)
			return
		}
		f, err := os.OpenFile(filepath.Join(c.Output, "result.pdf"), os.O_CREATE|os.O_EXCL|os.O_WRONLY, 0600)
		if err != nil {
			http.Error(w, "Result write failed", 500)
			return
		}
		_, err = f.Write(data)
		closeErr := f.Close()
		if err != nil || closeErr != nil {
			http.Error(w, "Result write failed", 500)
			return
		}
		state = "completed"
		sum := sha256.Sum256(data)
		fmt.Printf("ORIGIN_RESULT server=%s job=%s uuid=%s bytes=%d sha256=%x\n", c.ServerID, c.JobID, documentUUID, len(data), sum)
		w.WriteHeader(204)
	})
	upgrader := websocket.Upgrader{CheckOrigin: func(r *http.Request) bool { return r.Header.Get("Origin") == "" }}
	mux.HandleFunc("/control", func(w http.ResponseWriter, r *http.Request) {
		if !authorized(w, r) {
			return
		}
		ws, err := upgrader.Upgrade(w, r, nil)
		if err != nil {
			return
		}
		defer ws.Close()
		ws.SetReadLimit(1 << 20)
		disconnected := make(chan struct{})
		go func() {
			defer close(disconnected)
			for {
				var report observation
				if ws.ReadJSON(&report) != nil {
					return
				}
				mu.Lock()
				json.NewEncoder(reports).Encode(report)
				reports.Sync()
				mu.Unlock()
				fmt.Printf("TABLET %s %s disconnected=%t private=%t usb=%v\n", report.Operation, report.Status, report.Disconnected, report.PrivateEndpointOnly, report.USB)
			}
		}()
		for {
			select {
			case operation := <-controls:
				mu.Lock()
				terminal := state != "pending"
				mu.Unlock()
				if operation == "send" && terminal {
					fmt.Println("SEND_REJECTED terminal request")
					continue
				}
				if ws.WriteJSON(command{operation, c.ServerID, c.JobID, documentUUID}) != nil {
					return
				}
			case <-disconnected:
				return
			}
		}
	})
	go func() {
		scanner := bufio.NewScanner(os.Stdin)
		for scanner.Scan() {
			operation := strings.TrimSpace(scanner.Text())
			switch operation {
			case "cancel":
				mu.Lock()
				if state == "pending" {
					state = "cancelled"
				}
				mu.Unlock()
				fmt.Println("ORIGIN_CANCELLED")
			case "send", "import", "stop":
				controls <- operation
			default:
				fmt.Println("Commands: send, import, cancel, stop")
			}
		}
	}()
	server := http.Server{Addr: c.Address, Handler: mux, ReadHeaderTimeout: 10 * time.Second, ReadTimeout: 60 * time.Second, WriteTimeout: 60 * time.Second, TLSConfig: &tls.Config{MinVersion: tls.VersionTLS12}}
	fmt.Println("RECEIVER_READY", c.Address)
	return server.ListenAndServeTLS(c.Certificate, c.Key)
}

func tablet(c config) error {
	ca, err := os.ReadFile(c.CA)
	if err != nil {
		return err
	}
	roots := x509.NewCertPool()
	if !roots.AppendCertsFromPEM(ca) {
		return errors.New("Invalid experiment trust certificate")
	}
	tlsConfig := &tls.Config{MinVersion: tls.VersionTLS12, RootCAs: roots}
	base, err := url.Parse(c.Address)
	if err != nil || base.Scheme != "https" || base.Host == "" || base.Path != "" || base.User != nil {
		return errors.New("Desktop address must be an HTTPS origin")
	}
	client := &http.Client{Timeout: 45 * time.Second, Transport: &http.Transport{TLSClientConfig: tlsConfig, Proxy: nil}, CheckRedirect: func(*http.Request, []*http.Request) error { return errors.New("Redirect forbidden") }}
	local := &http.Client{Timeout: 30 * time.Second, Transport: &http.Transport{Proxy: nil}, CheckRedirect: func(*http.Request, []*http.Request) error { return errors.New("Local redirect forbidden") }}
	dialer := websocket.Dialer{TLSClientConfig: tlsConfig, HandshakeTimeout: 15 * time.Second, Proxy: nil}
	headers := http.Header{"Authorization": []string{"Bearer " + c.Token}}
	ws, _, err := dialer.Dial("wss://"+base.Host+"/control", headers)
	if err != nil {
		return err
	}
	defer ws.Close()
	ws.SetReadLimit(1 << 20)
	var mu sync.Mutex
	report := func(operation, status string) {
		o := observe()
		o.Operation = operation
		o.Status = status
		mu.Lock()
		defer mu.Unlock()
		ws.SetWriteDeadline(time.Now().Add(10 * time.Second))
		ws.WriteJSON(o)
	}
	done := make(chan struct{})
	defer close(done)
	go func() {
		ticker := time.NewTicker(3 * time.Second)
		defer ticker.Stop()
		for {
			select {
			case <-ticker.C:
				report("sample", "observed")
			case <-done:
				return
			}
		}
	}()
	report("ready", "connected")
	imported := false
	for {
		var action command
		if err := ws.ReadJSON(&action); err != nil {
			return err
		}
		if action.ServerID != c.ServerID || action.JobID != c.JobID || action.UUID != documentUUID {
			report("reject", "wrong binding")
			continue
		}
		if action.Operation == "stop" {
			report("stop", "accepted")
			return nil
		}
		o := observe()
		if !o.Disconnected || !o.PrivateEndpointOnly {
			report(action.Operation, "rejected: USB attached or unsafe listeners")
			continue
		}
		switch action.Operation {
		case "send":
			err = exportPDF(c, client, local)
			if err != nil {
				report("send", err.Error())
			} else {
				report("send", "uploaded")
			}
		case "import":
			if imported {
				report("import", "rejected: already attempted")
				continue
			}
			imported = true
			err = importPDF(c, client, local)
			if err != nil {
				report("import", err.Error())
			} else {
				report("import", "HTTP 201; owner visibility check required")
			}
		default:
			report("reject", "unknown operation")
		}
	}
}

func exportPDF(c config, remote, local *http.Client) error {
	response, err := local.Get(localURL + "/download/" + documentUUID + "/pdf")
	if err != nil {
		return errors.New("Local export transport failed")
	}
	defer response.Body.Close()
	if response.StatusCode != 200 {
		return fmt.Errorf("Local export HTTP %d", response.StatusCode)
	}
	data, err := io.ReadAll(io.LimitReader(response.Body, limit+1))
	if err != nil || len(data) > limit || !bytes.HasPrefix(data, []byte("%PDF-")) {
		return errors.New("Local export invalid PDF")
	}
	request, err := http.NewRequest("POST", c.Address+"/result", bytes.NewReader(data))
	if err != nil {
		return err
	}
	request.Header.Set("Authorization", "Bearer "+c.Token)
	request.Header.Set("Content-Type", "application/pdf")
	request.Header.Set("X-Server-ID", c.ServerID)
	request.Header.Set("X-Job-ID", c.JobID)
	request.Header.Set("X-Document-UUID", documentUUID)
	result, err := remote.Do(request)
	if err != nil {
		return errors.New("Authenticated PDF upload failed")
	}
	defer result.Body.Close()
	io.Copy(io.Discard, result.Body)
	if result.StatusCode != 204 {
		return fmt.Errorf("PDF receiver HTTP %d", result.StatusCode)
	}
	return nil
}

func importPDF(c config, remote, local *http.Client) error {
	request, err := http.NewRequest("GET", c.Address+"/source", nil)
	if err != nil {
		return err
	}
	request.Header.Set("Authorization", "Bearer "+c.Token)
	response, err := remote.Do(request)
	if err != nil {
		return errors.New("Authenticated source transfer failed")
	}
	defer response.Body.Close()
	if response.StatusCode != 200 {
		return fmt.Errorf("Source HTTP %d", response.StatusCode)
	}
	data, err := io.ReadAll(io.LimitReader(response.Body, limit+1))
	if err != nil || len(data) > limit {
		return errors.New("Source transfer invalid")
	}
	sum := sha256.Sum256(data)
	if hex.EncodeToString(sum[:]) != sourceHash {
		return errors.New("Source hash mismatch")
	}
	var body bytes.Buffer
	writer := multipart.NewWriter(&body)
	part, err := writer.CreateFormFile("file", "Pi Ink loopback 0014 synthetic.pdf")
	if err != nil {
		return err
	}
	if _, err = part.Write(data); err != nil {
		return err
	}
	if err = writer.Close(); err != nil {
		return err
	}
	request, err = http.NewRequest("POST", localURL+"/upload", &body)
	if err != nil {
		return err
	}
	request.Header.Set("Content-Type", writer.FormDataContentType())
	result, err := local.Do(request)
	if err != nil {
		return errors.New("Local import transport failed")
	}
	defer result.Body.Close()
	io.Copy(io.Discard, result.Body)
	if result.StatusCode != 201 {
		return fmt.Errorf("Local import HTTP %d", result.StatusCode)
	}
	return nil
}

func observe() observation {
	o := observation{Time: time.Now().UTC().Format(time.RFC3339Nano), USB: map[string]string{}, Disconnected: true}
	paths, err := filepath.Glob("/sys/class/udc/*/state")
	if err != nil || len(paths) != 2 {
		o.Disconnected = false
	}
	for _, path := range paths {
		data, err := os.ReadFile(path)
		state := strings.TrimSpace(string(data))
		o.USB[path] = state
		if err != nil || state != "not attached" {
			o.Disconnected = false
		}
	}
	interfaces, err := net.Interfaces()
	if err != nil {
		o.Disconnected = false
	}
	for _, iface := range interfaces {
		addresses, err := iface.Addrs()
		if err != nil {
			o.Disconnected = false
		}
		for _, address := range addresses {
			o.Addresses = append(o.Addresses, iface.Name+" "+address.String())
			if strings.HasPrefix(iface.Name, "usb") && strings.Contains(address.String(), ".") {
				o.Disconnected = false
			}
		}
	}
	o.PrivateEndpointOnly = true
	found := false
	for _, path := range []string{"/proc/net/tcp", "/proc/net/tcp6"} {
		data, err := os.ReadFile(path)
		if err != nil {
			o.PrivateEndpointOnly = false
		}
		for _, line := range strings.Split(string(data), "\n") {
			fields := strings.Fields(line)
			if len(fields) < 4 || fields[3] != "0A" {
				continue
			}
			address := fields[1]
			o.Listeners = append(o.Listeners, address)
			if strings.HasSuffix(address, ":0050") || strings.HasSuffix(address, ":0051") {
				if address != "0100007F:0051" {
					o.PrivateEndpointOnly = false
				} else {
					found = true
				}
			}
		}
	}
	o.PrivateEndpointOnly = o.PrivateEndpointOnly && found
	return o
}

func must(err error) {
	if err != nil {
		log.Fatal(err)
	}
}
